var i=144;var t=[{id:`cooking-144-01`,theoryId:144,type:`single_choice`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Which odor is a warning sign when buying raw fish?`,ua:`Який запах є тривожною ознакою під час купівлі сирої риби?`},explanation:{en:`FDA advises rejecting seafood with sour, rancid, fishy or ammonia odors.`,ua:`FDA радить відмовлятися від морепродуктів із кислим, прогірклим, різко рибним чи аміачним запахом.`},options:[{id:`a`,text:{en:`Strong ammonia or sour odor`,ua:`Різкий аміачний чи кислий запах`}},{id:`b`,text:{en:`Mild fresh sea smell`,ua:`Легкий свіжий морський запах`}},{id:`c`,text:{en:`No unpleasant smell`,ua:`Відсутність неприємного запаху`}}],answer:{optionIds:[`a`]}},{id:`cooking-144-02`,theoryId:144,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Freezing makes already spoiled fish safe again.`,ua:`Заморожування знову робить зіпсовану рибу безпечною.`},explanation:{en:`Freezing does not reverse spoilage or reliably eliminate every hazard.`,ua:`Заморожування не скасовує псування й не усуває надійно всі небезпеки.`},answer:{value:!1}},{id:`cooking-144-03`,theoryId:144,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match seafood shopping observations to actions.`,ua:`Поєднайте ознаки морепродуктів із діями.`},explanation:{en:`Cold-chain and packaging integrity matter together with fresh appearance.`,ua:`Холодовий ланцюг і цілісність упаковки важливі разом зі свіжістю.`},leftItems:[{id:`l1`,text:{en:`Fish stored cold on clean ice`,ua:`Риба на чистому льоду`}},{id:`l2`,text:{en:`Ammonia odor`,ua:`Аміачний запах`}},{id:`l3`,text:{en:`Torn frozen package`,ua:`Розірване заморожене пакування`}}],rightItems:[{id:`r3`,text:{en:`Avoid purchasing`,ua:`Не купувати`}},{id:`r2`,text:{en:`Reject`,ua:`Відмовитися від продукту`}},{id:`r1`,text:{en:`Acceptable storage condition to examine further`,ua:`Належна умова зберігання для подальшої оцінки`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-144-04`,theoryId:144,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Frozen fish in a store feels soft and has heavy frost inside a broken bag. What is prudent?`,ua:`Заморожена риба в магазині м’яка та в пошкодженому пакеті багато інею. Що робити?`},explanation:{en:`Signs of thawing or package damage are reasons to avoid the purchase.`,ua:`Ознаки розморожування чи пошкодження упаковки — підстава відмовитися від покупки.`},options:[{id:`a`,text:{en:`Select a different properly frozen package`,ua:`Обрати іншу належно заморожену упаковку`}},{id:`b`,text:{en:`Buy it because heavy frost proves freshness`,ua:`Купити, бо сильний іній доводить свіжість`}},{id:`c`,text:{en:`Leave it warm and refreeze later`,ua:`Тримати в теплі й знову заморозити`}}],answer:{optionIds:[`a`]}},{id:`cooking-144-05`,theoryId:144,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which fish-freshness claim is unsafe?`,ua:`Яке твердження про свіжість риби небезпечне?`},explanation:{en:`Strong unpleasant fishy odor can signal deterioration.`,ua:`Сильний неприємний рибний запах може свідчити про погіршення якості.`},options:[{id:`a`,text:{en:`Keep fish properly chilled`,ua:`Тримати рибу охолодженою`}},{id:`b`,text:{en:`Check for abnormal odors`,ua:`Перевіряти сторонні запахи`}},{id:`c`,text:{en:`A fishy smell is proof the seafood is perfectly fresh`,ua:`Різкий рибний запах доводить ідеальну свіжість`}}],answer:{optionIds:[`c`]}},{id:`cooking-144-06`,theoryId:144,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which observations may justify rejecting seafood at purchase?`,ua:`Які ознаки можуть бути підставою не купувати морепродукти?`},explanation:{en:`Off odor, bad cold chain and damaged packaging are red flags.`,ua:`Сторонній запах, порушення охолодження й пошкоджена упаковка — тривожні ознаки.`},options:[{id:`a`,text:{en:`Ammonia smell`,ua:`Аміачний запах`}},{id:`b`,text:{en:`Torn frozen package`,ua:`Порвана упаковка замороженого продукту`}},{id:`c`,text:{en:`Fish held without proper chilling`,ua:`Риба без належного охолодження`}},{id:`d`,text:{en:`Intact packaging and fresh mild smell`,ua:`Ціла упаковка й легкий свіжий запах`}}],answer:{optionIds:[`a`,`b`,`c`]}}];var n={theoryId:144,exercises:t};export{n as default,t as exercises,i as theoryId};